import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

// Only JxButton is taken from the package; table/badge markup rides the jx-* CSS
// contract from @jinx-ui/core, so verify class names against the installed version.

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
  pageSize?: number;
}

function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(0);

  const pageCount = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, pageCount - 1);

  const rows = useMemo(
    () => users.slice(currentPage * pageSize, currentPage * pageSize + pageSize),
    [users, currentPage, pageSize],
  );

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <table className="jx-table">
        <thead className="jx-table__head">
          <tr className="jx-table__row">
            <th className="jx-table__cell jx-table__cell--head" scope="col">
              Имя
            </th>
            <th className="jx-table__cell jx-table__cell--head" scope="col">
              Роль
            </th>
            <th className="jx-table__cell jx-table__cell--head" scope="col">
              Статус
            </th>
          </tr>
        </thead>
        <tbody className="jx-table__body">
          {rows.map((user) => (
            <tr className="jx-table__row" key={user.id}>
              <td className="jx-table__cell">{user.name}</td>
              <td className="jx-table__cell">{user.role}</td>
              <td className="jx-table__cell">
                <span
                  className={
                    user.status === 'active'
                      ? 'jx-badge jx-badge--success'
                      : 'jx-badge jx-badge--neutral'
                  }
                >
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Навигация по страницам"
        style={{ gap: 'var(--jx-space-2)', alignItems: 'center' }}
      >
        <JxButton
          variant="ghost"
          disabled={currentPage === 0}
          onClick={() => setPage(currentPage - 1)}
        >
          Назад
        </JxButton>

        {Array.from({ length: pageCount }, (_, index) => (
          <JxButton
            key={index}
            variant={index === currentPage ? 'primary' : 'ghost'}
            aria-current={index === currentPage ? 'page' : undefined}
            onClick={() => setPage(index)}
          >
            {index + 1}
          </JxButton>
        ))}

        <JxButton
          variant="ghost"
          disabled={currentPage >= pageCount - 1}
          onClick={() => setPage(currentPage + 1)}
        >
          Вперёд
        </JxButton>
      </nav>
    </div>
  );
}

export default UsersTable;

